        $uri = new Uri($url);
        $method = $vcrRequest->getMethod();
        $body = $vcrRequest->getBody();

        /** @var array<string, string|string[]> $headers */
        $headers = [];
        foreach ($vcrRequest->getHeaders() as $name => $value) {
