+        if ($parameter->in === 'path' && $style === 'label') {
+            return '.' . $this->delimitedValue($value, '.', $explode);
+        }
+
+        if ($parameter->in === 'path' && $style === 'matrix') {
+            return $this->matrix($parameter->name, $value, $explode);
+        }
