+     *
+     * @param list<string> $urls
+     */
+    public function add(string $key, array $urls, Interceptor $interceptor, Mode $mode): void
+    {
+        $this->urlsByKey[$key] = $urls;
+
+        foreach ($urls as $url) {
+            $this->interceptors[$url] ??= [];
+            $this->interceptors[$url][] = [
