+            return new Response(
+                $statusCode,
+                ['Content-Type' => $mediaType],
+                PayloadSerializer::serialize($data, $mediaType),
+            );
+        } catch (NoPath|NoResponse|JsonException $exception) {
+            throw FakeGenerationException::forOperation(strtoupper($method) . ' ' . $path, $exception);
+        }
+    }
+}
