+            $address = $this->validator->validateRequest($request);
+        } elseif ($definition !== null) {
+            $address = new OperationAddress($definition->pathPattern, $definition->method);
+        } else {
+            $address = null;
+        }
+
+        return new OperationRequest($path, $method, $definition, $address);
+    }
+}
