+        return new FakeRequest(
+            method: $definition->method,
+            baseUrl: $definition->serverUrls[0] ?? '/',
+            pathPattern: $definition->pathPattern,
+            pathParams: $parameters['path'],
+            queryParams: $parameters['query'],
+            headerParams: $headers,
+            rawBody: $body,
+        );
+    }
+}
