  2	
  3	declare(strict_types=1);
  4	
  5	namespace OasFake;
  6	
  7	use LogicException;
  8	
  9	/**
 10	 * Owns a server's interceptor and registry attachment state.
 11	 */
 12	final class ServerLifecycle
 13	{
 14	    private ?Interceptor $interceptor = null;
 15	
 16	    private ?ServerRegistry $registry = null;
 17	
 18	    private ?string $registryKey = null;
 19	
 20	    /**
 21	     * Reject configuration changes after the interceptor has started.
 22	     *
 23	     * @throws LogicException when the server is running
 24	     */
 25	    public function assertConfigurable(): void
 26	    {
 27	        if ($this->isRunning()) {
 28	            throw new LogicException('Cannot change server configuration while the server is running. Configure the server before start().');
 29	        }
 30	    }
 31	
 32	    /**
 33	     * Reject registration by a second registry.
 34	     *
 35	     * @throws LogicException when another registry owns the server
 36	     */
 37	    public function assertCanRegister(ServerRegistry $registry, string $key): void
 38	    {
 39	        if ($this->registry !== null && ($this->registry !== $registry || $this->registryKey !== $key)) {
 40	            throw new LogicException('Server is already registered in another ServerRegistry. Stop it before registering it again.');
 41	        }
 42	    }
 43	
 44	    /**
 45	     * Attach the server to its owning registry after successful construction.
 46	     *
 47	     * @throws LogicException when another registry owns the server
 48	     */
 49	    public function register(ServerRegistry $registry, string $key): void
 50	    {
 51	        $this->assertCanRegister($registry, $key);
 52	        $this->registry = $registry;
 53	        $this->registryKey = $key;
 54	    }
 55	
 56	    /**
 57	     * Return the owning registry and key, if registered.
 58	     *
 59	     * @return array{registry: ServerRegistry, key: string}|null
 60	     */
 61	    public function registration(): ?array
 62	    {
 63	        if ($this->registry === null || $this->registryKey === null) {
 64	            return null;
 65	        }
 66	
 67	        return [
 68	            'registry' => $this->registry,
 69	            'key' => $this->registryKey,
 70	        ];
 71	    }
 72	
 73	    /**
 74	     * Detach from a matching registry and stop the interceptor.
 75	     */
 76	    public function unregister(ServerRegistry $registry, string $key): void
 77	    {
 78	        if ($this->registry === $registry && $this->registryKey === $key) {
 79	            $this->registry = null;
 80	            $this->registryKey = null;
 81	        }
 82	
 83	        $this->stopInterceptor();
 84	    }
 85	
 86	    /**
 87	     * Replace the active interceptor after it has started successfully.
 88	     */
 89	    public function replaceInterceptor(Interceptor $interceptor): void
 90	    {
 91	        $this->interceptor = $interceptor;
 92	    }
 93	
 94	    /**
 95	     * Return the active interceptor, if one exists.
 96	     */
 97	    public function interceptor(): ?Interceptor
 98	    {
 99	        return $this->interceptor;
100	    }
101	
102	    /**
103	     * Report whether the active interceptor is running.
104	     */
105	    public function isRunning(): bool
106	    {
107	        return $this->interceptor !== null && $this->interceptor->isRunning();
108	    }
109	
110	    /**
111	     * Stop and release the active interceptor.
112	     */
113	    public function stopInterceptor(): void
114	    {
115	        if ($this->interceptor !== null) {
116	            $this->interceptor->stop();
117	            $this->interceptor = null;
118	        }
119	    }
120	}

