  1	<?php
  2	
  3	declare(strict_types=1);
  4	
  5	namespace OasFake;
  6	
  7	use OasFake\Exception\ReplayMismatchError;
  8	use Psr\Http\Server\MiddlewareInterface;
  9	use VCR\Request as VcrRequest;
 10	use VCR\Response as VcrResponse;
 11	
 12	/**
 13	 * Request handler with OpenAPI validation, fake response generation, and cassette management.
 14	 *
 15	 * Handles the full request lifecycle: conversion, validation, stub/faker resolution,
 16	 * middleware execution, and response conversion. Manages cassettes for RECORD/REPLAY modes.
 17	 *
 18	 * VCR lifecycle (turnOn/turnOff, hook registration) is managed externally by Server or ServerRegistry.
 19	 */
 20	final class Interceptor
 21	{
 22	    private bool $running = false;
 23	
 24	    private Mode $mode;
 25	
 26	    private Converter $converter;
 27	
 28	    private MiddlewarePipeline $middlewarePipeline;
 29	
 30	    private CassetteSession $cassetteSession;
 31	
 32	    private OperationRequestResolver $operationResolver;
 33	
 34	    private SchemaRequestHandler $requestHandler;
 35	
 36	    /**
 37	     * @param array{alwaysFakeOptionals?: bool, minItems?: int, maxItems?: int} $fakerOptions
 38	     * @param list<MiddlewareInterface> $middleware
 39	     */
 40	    public function __construct(
 41	        string|Mode $mode,
 42	        string $cassettePath,
 43	        Schema $schema,
 44	        Validator $validator,
 45	        array $fakerOptions,
 46	        HandlerMap $handlers,
 47	        bool $validateRequests,
 48	        bool $validateResponses,
 49	        array $middleware = [],
 50	        string $cassetteName = 'recording',
 51	    ) {
 52	        $this->mode = Mode::from($mode);
 53	        $this->converter = new Converter();
 54	        $fakeDataContext = new FakeDataContext($schema, $fakerOptions);
 55	        $this->operationResolver = new OperationRequestResolver(
 56	            $schema,
 57	            $fakeDataContext->operationLookup(),
 58	            new OperationPathResolver(),
 59	            $validator,
 60	            $validateRequests,
 61	        );
 62	        $this->requestHandler = new SchemaRequestHandler(
 63	            $this->operationResolver,
 64	            new OperationResponder($fakeDataContext, $handlers),
 65	            $validator,
 66	            $validateResponses,
 67	        );
 68	        $this->middlewarePipeline = new MiddlewarePipeline($middleware);
 69	        $this->cassetteSession = new CassetteSession($cassettePath, $cassetteName);
 70	    }
 71	
 72	    /**
 73	     * Activate the interceptor and initialize cassette for RECORD/REPLAY modes.
 74	     */
 75	    public function start(): void
 76	    {
 77	        if ($this->running) {
 78	            return;
 79	        }
 80	
 81	        if ($this->mode->isRecord() || $this->mode->isReplay()) {
 82	            $this->cassetteSession->start();
 83	        }
 84	
 85	        $this->running = true;
 86	    }
 87	
 88	    /**
 89	     * Deactivate the interceptor and release the cassette.
 90	     */
 91	    public function stop(): void
 92	    {
 93	        if (!$this->running) {
 94	            return;
 95	        }
 96	
 97	        $this->cassetteSession->stop();
 98	        $this->running = false;
 99	    }
100	
101	    /**
102	     * Check whether the interceptor is currently active.
103	     *
104	     * @return bool True if the interceptor has been started and not yet stopped
105	     */
106	    public function isRunning(): bool
107	    {
108	        return $this->running;
109	    }
110	
111	    /**
112	     * Handle an intercepted HTTP request and return a fake or validated response.
113	     *
114	     * Converts the VCR request to PSR-7, validates against the OpenAPI schema,
115	     * resolves a stub or generates a fake response, runs middleware, and converts back.
116	     * In RECORD mode, the request/response pair is also written to the cassette.
117	     *
