  3	declare(strict_types=1);
  4	
  5	namespace OasFake;
  6	
  7	use VCR\Request as VcrRequest;
  8	use VCR\Response as VcrResponse;
  9	
 10	/**
 11	 * Routes intercepted requests to the most specific registered server URL.
 12	 */
 13	final class InterceptorRouter
 14	{
 15	    /**
 16	     * @var array<string, list<array{key: string, interceptor: Interceptor, mode: Mode}>>
 17	     */
 18	    private array $interceptors = [];
 19	
 20	    /**
 21	     * @var array<string, list<string>>
 22	     */
 23	    private array $urlsByKey = [];
 24	
 25	    /**
 26	     * Create a router with URL matching semantics shared by operation lookup.
 27	     */
 28	    public function __construct(private ServerUrlMatcher $urlMatcher)
 29	    {
 30	    }
 31	
 32	    /**
 33	     * Add an interceptor under every effective server URL.
 34	     *
 35	     * @param list<string> $urls
 36	     */
 37	    public function add(string $key, array $urls, Interceptor $interceptor, Mode $mode): void
 38	    {
 39	        $this->urlsByKey[$key] = $urls;
 40	
 41	        foreach ($urls as $url) {
 42	            $this->interceptors[$url] ??= [];
 43	            $this->interceptors[$url][] = [
 44	                'key' => $key,
 45	                'interceptor' => $interceptor,
 46	                'mode' => $mode,
 47	            ];
 48	        }
 49	    }
 50	
 51	    /**
 52	     * Remove every route owned by a server key.
 53	     */
 54	    public function remove(string $key): void
 55	    {
 56	        foreach ($this->urlsByKey[$key] ?? [] as $url) {
 57	            $remaining = [];
 58	            foreach ($this->interceptors[$url] ?? [] as $entry) {
 59	                if ($entry['key'] !== $key) {
 60	                    $remaining[] = $entry;
 61	                }
 62	            }
 63	
 64	            if ($remaining === []) {
 65	                unset($this->interceptors[$url]);
 66	            } else {
 67	                $this->interceptors[$url] = $remaining;
 68	            }
 69	        }
 70	
 71	        unset($this->urlsByKey[$key]);
 72	    }
 73	
 74	    /**
 75	     * Remove all registered routes.
 76	     */
 77	    public function clear(): void
 78	    {
 79	        $this->interceptors = [];
 80	        $this->urlsByKey = [];
 81	    }
 82	
 83	    /**
 84	     * Dispatch a request, or return null when no registered URL matches.
 85	     */
 86	    public function dispatch(VcrRequest $request): ?VcrResponse
 87	    {
 88	        $url = $request->getUrl() ?? '';
 89	        $match = null;
 90	
 91	        foreach ($this->interceptors as $baseUrl => $entries) {
 92	            $specificity = $this->urlMatcher->specificity($url, $baseUrl);
 93	            if ($specificity === null) {
 94	                continue;
 95	            }
 96	
 97	            $entry = $entries[count($entries) - 1] ?? null;
 98	            if ($entry !== null && ($match === null || $specificity > $match['specificity'])) {
 99	                $match = [
100	                    'specificity' => $specificity,
101	                    'entry' => $entry,
102	                ];
103	            }
104	        }
105	
106	        if ($match === null) {
107	            return null;
108	        }
109	
110	        $entry = $match['entry'];
111	
112	        return $entry['mode']->isReplay()
113	            ? $entry['interceptor']->replay($request)
114	            : $entry['interceptor']->handle($request);
115	    }
116	}

