20	     * Return every effective server URL used by at least one operation.
21	     *
22	     * @return list<string>
23	     */
24	    public function all(OpenApi $openApi): array
25	    {
26	        $urls = [];
27	
28	        if ($openApi->paths !== null) {
29	            /** @var PathItem $pathItem */
30	            foreach ($openApi->paths as $path => $pathItem) {
31	                if (!is_string($path)) {
32	                    continue;
33	                }
34	
35	                foreach ($pathItem->getOperations() as $operation) {
36	                    foreach ($this->effective($openApi, $pathItem, $operation) as $url) {
37	                        $urls[$url] = true;
38	                    }
39	                }
40	            }
41	        }
42	
