46	    /**
47	     * Return server URLs using operation, path, and document precedence.
48	     *
49	     * @return list<string>
50	     */
51	    public function effective(OpenApi $openApi, ?PathItem $pathItem = null, ?Operation $operation = null): array
52	    {
53	        if ($operation !== null && $operation->servers !== null && $operation->servers !== []) {
54	            return $this->substituteVariables($operation->servers);
55	        }
56	
57	        if ($pathItem !== null && $pathItem->servers !== null && $pathItem->servers !== []) {
58	            return $this->substituteVariables($pathItem->servers);
59	        }
60	
61	        if ($openApi->servers !== null && $openApi->servers !== []) {
62	            return $this->substituteVariables($openApi->servers);
63	        }
64	
65	        return ['/'];
66	    }
67	
68	    /**
69	     * Substitute defaults for variables in a list of OpenAPI servers.
70	     *
71	     * @param array<int|string, CebeServer> $servers
72	     *
73	     * @return list<string>
74	     */
75	    public function substituteVariables(array $servers): array
76	    {
77	        $urls = [];
78	
79	        foreach ($servers as $server) {
80	            if (!$server instanceof CebeServer) {
81	                continue;
82	            }
83	
84	            $url = $server->url;
85	            if ($server->variables !== null) {
86	                foreach ($server->variables as $name => $variable) {
87	                    $url = str_replace('{' . $name . '}', $variable->default, $url);
