 24	     * }
 25	     */
 26	    public function build(Schema $schema): array
 27	    {
 28	        $byOperationId = [];
 29	        $byPathMethod = [];
 30	        $openApi = $schema->openApi();
 31	
 32	        if ($openApi->paths === null) {
 33	            return [
 34	                'byOperationId' => $byOperationId,
 35	                'byPathMethod' => $byPathMethod,
 36	            ];
 37	        }
 38	
 39	        /** @var PathItem $pathItem */
 40	        foreach ($openApi->paths as $pathPattern => $pathItem) {
 41	            if (!is_string($pathPattern)) {
 42	                continue;
 43	            }
 44	
 45	            $pathParameters = [];
 46	            if ($pathItem->parameters !== null) {
 47	                foreach ($pathItem->parameters as $parameter) {
 48	                    if ($parameter instanceof Parameter) {
 49	                        $pathParameters[] = $parameter;
 50	                    }
 51	                }
 52	            }
 53	
 54	            foreach (['get', 'post', 'put', 'delete', 'patch', 'options', 'head', 'trace'] as $method) {
 55	                $operation = match ($method) {
 56	                    'get' => $pathItem->get,
 57	                    'post' => $pathItem->post,
 58	                    'put' => $pathItem->put,
 59	                    'delete' => $pathItem->delete,
 60	                    'patch' => $pathItem->patch,
 61	                    'options' => $pathItem->options,
 62	                    'head' => $pathItem->head,
 63	                    'trace' => $pathItem->trace,
 64	                };
 65	                if (!$operation instanceof Operation) {
 66	                    continue;
 67	                }
 68	
 69	                /** @var array<string, Parameter> $mergedParameters */
 70	                $mergedParameters = [];
 71	                foreach ($pathParameters as $parameter) {
 72	                    $mergedParameters[$parameter->in . ':' . $parameter->name] = $parameter;
 73	                }
 74	                if ($operation->parameters !== null) {
 75	                    foreach ($operation->parameters as $parameter) {
 76	                        if ($parameter instanceof Parameter) {
 77	                            $mergedParameters[$parameter->in . ':' . $parameter->name] = $parameter;
 78	                        }
 79	                    }
 80	                }
 81	
 82	                $operationId = $operation->operationId ?? '';
 83	                $definition = new OperationDefinition(
 84	                    pathPattern: $pathPattern,
 85	                    method: $method,
 86	                    operationId: $operationId,
 87	                    operation: $operation,
 88	                    parameters: array_values($mergedParameters),
 89	                    serverUrls: $schema->effectiveServerUrls($pathItem, $operation),
 90	                );
