 5	namespace OasFake;
 6	
 7	use LogicException;
 8	use OasFake\Exception\ReplayMismatchError;
 9	use VCR\Cassette;
10	use VCR\Configuration;
11	use VCR\Request as VcrRequest;
12	use VCR\Response as VcrResponse;
13	use VCR\Storage\Json;
14	
15	/**
16	 * Owns one interceptor's cassette and per-request playback indexes.
17	 */
18	final class CassetteSession
19	{
20	    private ?Cassette $cassette = null;
21	
22	    /** @var array<string, int> */
23	    private array $indexTable = [];
24	
25	    /**
26	     * Create a cassette session for a storage path and cassette name.
27	     */
28	    public function __construct(private string $path, private string $name)
29	    {
30	    }
31	
32	    /**
33	     * Open the configured cassette.
34	     */
35	    public function start(): void
36	    {
37	        $this->cassette = new Cassette(
38	            $this->name,
39	            new Configuration(),
40	            new Json($this->path, $this->name),
41	        );
42	    }
43	
44	    /**
45	     * Release cassette state and playback positions.
46	     */
47	    public function stop(): void
48	    {
49	        $this->cassette = null;
50	        $this->indexTable = [];
51	    }
52	
53	    /**
54	     * Replay the next matching response.
55	     *
56	     * @throws ReplayMismatchError when the cassette is closed or has no matching response
57	     */
58	    public function playback(VcrRequest $request): VcrResponse
59	    {
60	        if ($this->cassette === null) {
61	            throw ReplayMismatchError::forRequest($request, new LogicException('No cassette loaded for replay'));
62	        }
63	
64	        $response = $this->cassette->playback($request, $this->nextIndex($request));
65	        if ($response === null) {
66	            throw ReplayMismatchError::forRequest($request, new LogicException('No matching cassette recording'));
67	        }
68	
69	        return $response;
70	    }
71	
72	    /**
73	     * Record a response when the cassette is open.
74	     */
75	    public function record(VcrRequest $request, VcrResponse $response): void
76	    {
77	        if ($this->cassette !== null) {
78	            $this->cassette->record($request, $response, $this->nextIndex($request));
79	        }
80	    }
81	
82	    /**
83	     * Advance and return the index for an equivalent request signature.
84	     */
85	    public function nextIndex(VcrRequest $request): int
86	    {
87	        $key = $request->getMethod() . ' ' . ($request->getUrl() ?? '');
88	        if (!isset($this->indexTable[$key])) {
89	            $this->indexTable[$key] = -1;
90	        }
91	
92	        return ++$this->indexTable[$key];
93	    }
94	}

