 5	namespace OasFake;
 6	
 7	use ReflectionClass;
 8	use ReflectionException;
 9	use ReflectionMethod;
10	
11	/**
12	 * Registers public server methods as declarative handlers.
13	 */
14	final class DeclarativeHandlerRegistrar
15	{
16	    /**
17	     * Register operationId and Route attribute handlers from the given server.
18	     *
19	     * @throws ReflectionException when a declared route attribute cannot be instantiated
20	     */
21	    public function register(Server $server, HandlerMap $handlers, ?Schema $schema = null): void
22	    {
23	        $reflection = new ReflectionClass($server);
24	        $operationLookup = $schema === null ? null : new OperationLookup($schema);
25	        $inspector = new DeclarativeHandlerInspector();
26	
27	        foreach ($reflection->getMethods(ReflectionMethod::IS_PUBLIC) as $method) {
28	            if (!$inspector->isCandidate($method)) {
29	                continue;
30	            }
31	
32	            $closure = $method->getClosure($server);
33	            if ($closure === null) {
34	                continue;
35	            }
36	
37	            $routeAttr = $inspector->route($method);
38	            if ($routeAttr !== null) {
39	                if ($operationLookup !== null && $operationLookup->findByPathAndMethod($routeAttr->path, $routeAttr->method) === null) {
40	                    continue;
41	                }
42	
43	                $handlers->forPath(
44	                    $routeAttr->path,
45	                    $routeAttr->method,
46	                    Handler::callback($closure),
47	                );
48	
49	                continue;
50	            }
51	
52	            if ($operationLookup !== null && $operationLookup->findByOperationId($method->getName()) === null) {
53	                continue;
54	            }
55	
56	            $handlers->forOperation(
57	                $method->getName(),
58	                Handler::callback($closure),
59	            );
60	        }
61	    }
62	}

