  3	declare(strict_types=1);
  4	
  5	namespace OasFake;
  6	
  7	use Closure;
  8	use GuzzleHttp\Psr7\Response;
  9	use InvalidArgumentException;
 10	
 11	use function is_array;
 12	use function json_encode;
 13	
 14	use const JSON_THROW_ON_ERROR;
 15	
 16	use JsonException;
 17	use OasFake\Exception\HandlerResolutionException;
 18	use Psr\Http\Message\ResponseInterface;
 19	use Psr\Http\Message\ServerRequestInterface;
 20	
 21	/**
 22	 * Represents a handler for a specific API operation.
 23	 */
 24	final class Handler
 25	{
 26	    /**
 27	     * @param array<string, mixed>|list<mixed>|string|null $body
 28	     * @param array<string, string> $headers
 29	     * @param (Closure(ServerRequestInterface, ?ResponseInterface): ResponseInterface)|null $callback
 30	     *
 31	     * @throws InvalidArgumentException when callback and fixed-response state are mixed or incomplete
 32	     */
 33	    public function __construct(
 34	        private ?int $statusCode,
 35	        private array|string|null $body,
 36	        private array $headers,
 37	        private ?Closure $callback,
 38	    ) {
 39	        if ($callback !== null && ($statusCode !== null || $body !== null || $headers !== [])) {
 40	            throw new InvalidArgumentException('Callback handlers cannot also define a fixed response.');
 41	        }
 42	
 43	        if ($callback === null && $statusCode === null) {
 44	            throw new InvalidArgumentException('Fixed response handlers require a status code.');
 45	        }
 46	    }
 47	
 48	    /**
 49	     * @param array<string, mixed>|list<mixed>|string $body
 50	     * @param array<string, string> $headers
 51	     */
 52	    public static function response(int $status, array|string $body, array $headers = []): self
 53	    {
 54	        return new self($status, $body, $headers, null);
 55	    }
 56	
 57	    /**
 58	     * Create a handler that delegates response generation to a callback.
 59	     *
 60	     * @param callable(ServerRequestInterface, ?ResponseInterface): ResponseInterface $callback
 61	     */
 62	    public static function callback(callable $callback): self
 63	    {
 64	        return new self(null, null, [], Closure::fromCallable($callback));
 65	    }
 66	
 67	    /**
 68	     * Create a handler that returns an empty response with the given status code.
 69	     *
 70	     * @param int $status The HTTP status code
 71	     */
 72	    public static function status(int $status): self
 73	    {
 74	        return new self($status, null, [], null);
 75	    }
 76	
 77	    /**
 78	     * Resolve the handler into a PSR-7 response.
 79	     *
 80	     * For callback handlers, invokes the callback with the request and an optional default response.
 81	     * For response handlers, returns the configured body.
 82	     * For status handlers, returns an empty response with the configured status.
 83	     *
 84	     * @param ServerRequestInterface $request The incoming request
 85	     * @param ResponseInterface|null $default An optional faker-generated default response
 86	     *
 87	     * @throws HandlerResolutionException when a fixed array body cannot be encoded
 88	     *
 89	     * @return ResponseInterface The resolved response
 90	     */
 91	    public function resolve(ServerRequestInterface $request, ?ResponseInterface $default = null): ResponseInterface
 92	    {
 93	        if ($this->callback !== null) {
 94	            return ($this->callback)($request, $default);
 95	        }
 96	
 97	        $statusCode = $this->statusCode ?? 200;
 98	        $headers = $this->headers;
 99	
100	        if ($this->body === null) {
101	            return new Response($statusCode, $headers);
102	        }
103	
104	        try {
105	            $body = is_array($this->body) ? json_encode($this->body, JSON_THROW_ON_ERROR) : $this->body;
106	        } catch (JsonException $exception) {
