25	     * @param (callable(T): T)|null $configure Optional fluent configuration callback
26	     *
27	     * @return T
28	     */
29	    public static function start(string|Server $server, ?callable $configure = null): Server
30	    {
31	        if (is_string($server)) {
32	            /** @var T $server */
33	            $server = new $server();
34	        }
35	
36	        if ($configure !== null) {
37	            $server = $configure($server);
38	        }
39	
40	        (self::$registry ??= new ServerRegistry())->register(
41	            $server::class . '#' . spl_object_id($server),
42	            $server,
43	        );
44	
