    14	/**
    15	 * Owns the process-wide PHP-VCR activation and dispatch hook lifecycle.
    16	 */
    17	final class VcrLifecycle
    18	{
    19	    private bool $active = false;
    20	
    21	    /**
    22	     * Activate PHP-VCR once and bind intercepted requests to a dispatcher.
    23	     *
    24	     * @param callable(VcrRequest): VcrResponse $dispatch
    25	     */
    26	    public function activate(callable $dispatch): void
    27	    {
    28	        if ($this->active) {
    29	            return;
    30	        }
    31	
    32	        VCR::configure()
    33	            ->setCassettePath(sys_get_temp_dir())
    34	            ->setStorage('json')
    35	            ->setMode('none')
    36	            ->enableLibraryHooks(['curl', 'stream_wrapper']);
    37	        VCR::turnOn();
    38	        VCR::insertCassette('oas-fake-registry');
    39	
    40	        $handler = Closure::fromCallable($dispatch);
    41	        foreach (VCR::configure()->getLibraryHooks() as $hookClass) {
    42	            /** @var LibraryHook $hook */
    43	            $hook = VCRFactory::get($hookClass);
    44	            $hook->disable();
    45	            $hook->enable($handler);
    46	        }
    47	
    48	        $this->active = true;
    49	    }
